/* s32utf.h -- the one Unicode model for SLOW-32's text: UTF-8 and
 * UTF-16BE coding, display width, and grapheme clusters (UAX #29).
 *
 * Shared, header-only, by everything that measures or moves text: the
 * term service (tools/emulator/mmio_ring.c, and QEMU's copy), the COBOL
 * runtime (cobol/libcob) and the COBOL compiler.  One model, so the
 * screen, a report line and the compiler never disagree about where a
 * character ends or how many columns it takes.
 *
 * The width, Grapheme_Cluster_Break and Extended_Pictographic data are
 * libutf's DFAs (s32utf_tables.h, generated by gen_s32utf.py), run here
 * the way libutf runs them.  Cluster width is tinymux's policy
 * (libutf color_ops cluster_console_width): the widest code point in
 * the cluster; a regional-indicator pair, and anything carrying U+FE0F,
 * is two.  Unicode 16.0, less GB9c (Indic conjunct breaks), which libutf
 * does not implement either.
 *
 * Decoding is strict and never loses a byte: a byte that begins no
 * sequence, or a sequence cut short, is one U+FFFD per maximal subpart
 * (Unicode 16.0 section 3.9, "U+FFFD substitution of maximal subparts"),
 * and the byte that cut a sequence short is decoded again. */
#ifndef S32UTF_H
#define S32UTF_H

#include <stddef.h>
#include <stdint.h>
#include "s32utf_tables.h"

#define S32U_REPL 0xFFFDu

/* ---- UTF-8, one byte at a time ------------------------------------------ */

typedef struct { uint32_t cp; int need; unsigned lo, hi; } s32u_dec;

/* Feed one byte.  0: more bytes wanted.  1: *cp is a code point.  2: *cp
 * is U+FFFD for a sequence this byte cut short, and the byte must be fed
 * again. */
static inline int s32u_dec_byte(s32u_dec *d, unsigned b, uint32_t *cp)
{
    b &= 0xFF;
    if (d->need) {
        if (b >= d->lo && b <= d->hi) {
            d->cp = d->cp << 6 | (b & 0x3F);
            d->lo = 0x80; d->hi = 0xBF;
            if (--d->need) return 0;
            *cp = d->cp;
            return 1;
        }
        d->need = 0;
        *cp = S32U_REPL;
        return 2;
    }
    if (b < 0x80) { *cp = b; return 1; }
    d->lo = 0x80; d->hi = 0xBF;
    if (b >= 0xC2 && b <= 0xDF) { d->need = 1; d->cp = b & 0x1F; return 0; }
    if (b >= 0xE0 && b <= 0xEF) {
        d->need = 2; d->cp = b & 0x0F;
        if (b == 0xE0) d->lo = 0xA0;            /* no overlong forms */
        if (b == 0xED) d->hi = 0x9F;            /* no surrogates */
        return 0;
    }
    if (b >= 0xF0 && b <= 0xF4) {
        d->need = 3; d->cp = b & 0x07;
        if (b == 0xF0) d->lo = 0x90;
        if (b == 0xF4) d->hi = 0x8F;            /* nothing past U+10FFFF */
        return 0;
    }
    *cp = S32U_REPL;                            /* 80-C1, F5-FF: no sequence */
    return 1;
}

/* At the end of the input: 1 and U+FFFD when a sequence was left open. */
static inline int s32u_dec_end(s32u_dec *d, uint32_t *cp)
{
    if (!d->need) return 0;
    d->need = 0;
    *cp = S32U_REPL;
    return 1;
}

/* One code point from p[0..n), n >= 1: the bytes it took (at least 1). */
static inline size_t s32u_decode(const unsigned char *p, size_t n, uint32_t *cp)
{
    s32u_dec d = { 0, 0, 0, 0 };
    for (size_t i = 0; i < n; i++) {
        int r = s32u_dec_byte(&d, p[i], cp);
        if (r == 1) return i + 1;
        if (r == 2) return i;                   /* i >= 1: the lead byte came first */
    }
    s32u_dec_end(&d, cp);
    return n;
}

/* A code point as UTF-8 (a surrogate or anything past U+10FFFF as
 * U+FFFD): the bytes written, 1 to 4. */
static inline int s32u_encode(uint32_t cp, unsigned char *out)
{
    if ((cp >= 0xD800 && cp <= 0xDFFF) || cp > 0x10FFFF) cp = S32U_REPL;
    if (cp < 0x80) { out[0] = (unsigned char)cp; return 1; }
    if (cp < 0x800) { out[0] = (unsigned char)(0xC0 | cp >> 6); out[1] = (unsigned char)(0x80 | (cp & 0x3F)); return 2; }
    if (cp < 0x10000) {
        out[0] = (unsigned char)(0xE0 | cp >> 12); out[1] = (unsigned char)(0x80 | (cp >> 6 & 0x3F));
        out[2] = (unsigned char)(0x80 | (cp & 0x3F));
        return 3;
    }
    out[0] = (unsigned char)(0xF0 | cp >> 18); out[1] = (unsigned char)(0x80 | (cp >> 12 & 0x3F));
    out[2] = (unsigned char)(0x80 | (cp >> 6 & 0x3F)); out[3] = (unsigned char)(0x80 | (cp & 0x3F));
    return 4;
}

/* ---- UTF-16BE (COBOL national data) --------------------------------------- */

static inline unsigned s32u_u16_at(const unsigned char *p, size_t i) { return (unsigned)p[2 * i] << 8 | p[2 * i + 1]; }

/* The code point at code unit i of n: the units it took (1, or 2 for a
 * surrogate pair); a lone surrogate is U+FFFD. */
static inline size_t s32u_u16_get(const unsigned char *p, size_t n, size_t i, uint32_t *cp)
{
    unsigned u = s32u_u16_at(p, i);
    if (u >= 0xD800 && u <= 0xDBFF && i + 1 < n) {
        unsigned l = s32u_u16_at(p, i + 1);
        if (l >= 0xDC00 && l <= 0xDFFF) { *cp = 0x10000 + ((u - 0xD800) << 10) + (l - 0xDC00); return 2; }
    }
    *cp = (u >= 0xD800 && u <= 0xDFFF) ? S32U_REPL : u;
    return 1;
}

/* A code point as UTF-16BE at p: the units written (1 or 2); a surrogate
 * or anything past U+10FFFF is U+FFFD. */
static inline int s32u_u16_put(unsigned char *p, uint32_t cp)
{
    if ((cp >= 0xD800 && cp <= 0xDFFF) || cp > 0x10FFFF) cp = S32U_REPL;
    if (cp < 0x10000) { p[0] = (unsigned char)(cp >> 8); p[1] = (unsigned char)cp; return 1; }
    cp -= 0x10000;
    unsigned h = 0xD800 + (cp >> 10), l = 0xDC00 + (cp & 0x3FF);
    p[0] = (unsigned char)(h >> 8); p[1] = (unsigned char)h; p[2] = (unsigned char)(l >> 8); p[3] = (unsigned char)l;
    return 2;
}

static inline int s32u_u16_units(uint32_t cp) { return cp >= 0x10000 && cp <= 0x10FFFF ? 2 : 1; }

/* ---- properties: libutf's DFAs over a code point's UTF-8 ------------------ */

/* the width DFA (libutf console_width.c): 16-bit transitions, a run marker
 * y >= 128 standing for 256 - y literal columns */
static inline int s32u_cp_width(uint32_t cp)
{
    unsigned char b[4];
    int n = s32u_encode(cp, b), i = 0, state = S32U_TR_WIDTHS_START_STATE;
    while (state < S32U_TR_WIDTHS_ACCEPTING_STATES_START && i < n) {
        int col = s32u_tr_widths_itt[b[i++]];
        int off = s32u_tr_widths_sot[state];
        for (;;) {
            int y = s32u_tr_widths_sbt[off];
            if (y < 128) {
                if (col < y) { state = s32u_tr_widths_sbt[off + 1]; break; }
                col -= y; off += 2;
            } else {
                y = 256 - y;
                if (col < y) { state = s32u_tr_widths_sbt[off + col + 1]; break; }
                col -= y; off += y + 1;
            }
        }
    }
    return state >= S32U_TR_WIDTHS_ACCEPTING_STATES_START ? state - S32U_TR_WIDTHS_ACCEPTING_STATES_START : 1;
}

/* the 8-bit DFAs (libutf grapheme.c run_dfa): a signed run marker */
static inline int s32u_run8(const unsigned char *itt, const unsigned short *sot, const unsigned char *sbt,
                            int start, int accept, int dflt, uint32_t cp)
{
    unsigned char b[4];
    int n = s32u_encode(cp, b), i = 0, state = start;
    while (i < n && state < accept) {
        int col = itt[b[i++]];
        int off = sot[state];
        for (;;) {
            int y = (signed char)sbt[off];
            if (y > 0) {
                if (col < y) { state = sbt[off + 1]; break; }
                col -= y; off += 2;
            } else {
                y = -y;
                if (col < y) { state = sbt[off + col + 1]; break; }
                col -= y; off += y + 1;
            }
        }
    }
    return state >= accept ? state - accept : dflt;
}

enum { S32U_GCB_OTHER, S32U_GCB_CR, S32U_GCB_LF, S32U_GCB_CONTROL, S32U_GCB_EXTEND, S32U_GCB_ZWJ,
       S32U_GCB_RI, S32U_GCB_PREPEND, S32U_GCB_SPACINGMARK, S32U_GCB_L, S32U_GCB_V, S32U_GCB_T,
       S32U_GCB_LV, S32U_GCB_LVT };

static inline int s32u_gcb(uint32_t cp)
{
    return s32u_run8(s32u_tr_gcb_itt, s32u_tr_gcb_sot, s32u_tr_gcb_sbt, S32U_TR_GCB_START_STATE,
                     S32U_TR_GCB_ACCEPTING_STATES_START, S32U_GCB_OTHER, cp);
}

static inline int s32u_extpict(uint32_t cp)
{
    return s32u_run8(s32u_cl_extpict_itt, s32u_cl_extpict_sot, s32u_cl_extpict_sbt, S32U_CL_EXTPICT_START_STATE,
                     S32U_CL_EXTPICT_ACCEPTING_STATES_START, 0, cp) == 1;
}

/* ---- grapheme clusters, a code point at a time ------------------------------ */

/* The cluster being built.  Zero it to start (or after anything that
 * ends text, such as a cursor move). */
typedef struct {
    int started;
    int prev;          /* the last code point's GCB */
    int ri;            /* regional indicators in the cluster (GB12/13: they pair only when adjacent,
                          which libutf's count misses -- see its RI x Extend x RI case) */
    int epez;          /* ExtPict Extend* seen, for GB11 */
    int base;          /* the first code point's GCB */
    int ncp, wmax, vs16;
} s32u_clu;

/* 1 when cp starts a new cluster (a break before it), 0 when it joins the
 * one being built; either way the state then describes cp's cluster.
 * The rules are UAX #29's, in libutf utf_grapheme_next's order. */
static inline int s32u_clu_step(s32u_clu *c, uint32_t cp)
{
    int g = s32u_gcb(cp), ep = s32u_extpict(cp), join = 0;
    if (c->started) {
        int p = c->prev;
        if (p == S32U_GCB_CR && g == S32U_GCB_LF) join = 1;                                    /* GB3 */
        else if (p == S32U_GCB_CONTROL || p == S32U_GCB_CR || p == S32U_GCB_LF) join = 0;      /* GB4 */
        else if (g == S32U_GCB_CONTROL || g == S32U_GCB_CR || g == S32U_GCB_LF) join = 0;      /* GB5 */
        else if (p == S32U_GCB_L && (g == S32U_GCB_L || g == S32U_GCB_V || g == S32U_GCB_LV || g == S32U_GCB_LVT)) join = 1;  /* GB6 */
        else if ((p == S32U_GCB_LV || p == S32U_GCB_V) && (g == S32U_GCB_V || g == S32U_GCB_T)) join = 1;                   /* GB7 */
        else if ((p == S32U_GCB_LVT || p == S32U_GCB_T) && g == S32U_GCB_T) join = 1;                                      /* GB8 */
        else if (g == S32U_GCB_EXTEND || g == S32U_GCB_ZWJ) join = 1;                          /* GB9 */
        else if (g == S32U_GCB_SPACINGMARK) join = 1;                                          /* GB9a */
        else if (p == S32U_GCB_PREPEND) join = 1;                                              /* GB9b */
        else if (c->epez && p == S32U_GCB_ZWJ && ep) join = 1;                                 /* GB11 */
        else if (g == S32U_GCB_RI && p == S32U_GCB_RI && c->ri % 2 == 1) join = 1;             /* GB12/13 */
    }
    if (!join) {
        c->started = 1; c->base = g; c->ri = 0; c->epez = ep;
        c->ncp = 0; c->wmax = 0; c->vs16 = 0;
    } else if (ep) c->epez = 1;
    else if (g != S32U_GCB_EXTEND && g != S32U_GCB_ZWJ) c->epez = 0;
    if (g == S32U_GCB_RI) c->ri++;
    c->prev = g;
    c->ncp++;
    int w = s32u_cp_width(cp);
    if (w > c->wmax) c->wmax = w;
    if (cp == 0xFE0F) c->vs16 = 1;
    return !join;
}

/* The cluster's display width: 0, 1 or 2 (tinymux's policy, above). */
static inline int s32u_clu_width(const s32u_clu *c)
{
    if (c->base == S32U_GCB_RI && c->ncp >= 2) return 2;
    if (c->vs16 && c->wmax < 2) return 2;
    return c->wmax;
}

/* A cluster that starts with a mark has nothing to sit on: it is shown
 * over a space, one column. */
static inline int s32u_clu_lone(const s32u_clu *c)
{
    return c->base == S32U_GCB_EXTEND || c->base == S32U_GCB_ZWJ;
}

#endif
